// src/pages/CreateArticlePage.js
import React, { useState, useEffect } from "react";
import { contentFactory } from "../contentFactory";
import "../styles/CreateArticlesAdmin.css";

export default function CreateArticlePage() {
  const [mode, setMode] = useState("standard"); // стандартна чи для каналу
  const [subtype, setSubtype] = useState("standard"); // підтип
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [excerpt, setExcerpt] = useState("");
  const [image, setImage] = useState(null);
  const [category, setCategory] = useState("sport");
  const [isPremium, setIsPremium] = useState(false);
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("token");

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/channels/")
      .then((res) => res.json())
      .then((data) => setChannels(data))
      .catch(() => setChannels([]));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    const createContent = contentFactory(mode, token);

    const articleData = {
      title,
      content,
      excerpt,
      is_premium: isPremium,
      type: mode,
      subtype,
      category,
      channel: selectedChannel,
      image,
    };

    try {
      await createContent(articleData);
      setMessage("✅ Статтю успішно створено!");
      setTitle("");
      setContent("");
      setExcerpt("");
      setImage(null);
      setIsPremium(false);
      setSelectedChannel("");
      setSubtype("standard");
    } catch (err) {
      console.error("Помилка створення:", err);
      setMessage("❌ Не вдалося створити статтю");
    }
  };

  return (
    <div className="create-article-container">
      <h2 className="create-article-title">Створити статтю</h2>
      <form onSubmit={handleSubmit} className="create-article-form">
        <label>
          Тип статті:
          <select
            className="create-article-select"
            value={mode}
            onChange={(e) => setMode(e.target.value)}
          >
            <option value="standard">Звичайна (категорії)</option>
            <option value="channel">Для каналу</option>
          </select>
        </label>

        <label>
          Формат статті:
          <select
            className="create-article-select"
            value={subtype}
            onChange={(e) => setSubtype(e.target.value)}
          >
            <option value="standard">Звичайна</option>
            <option value="no_photo">Без фото</option>
            <option value="no_photo_no_comments">
              Без фото і без коментарів
            </option>
          </select>
        </label>

        <input
          className="create-article-input"
          type="text"
          placeholder="Заголовок"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />

        <textarea
          className="create-article-textarea"
          placeholder="Текст статті"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          required
        />

        <textarea
          className="create-article-textarea"
          placeholder="Короткий опис"
          value={excerpt}
          onChange={(e) => setExcerpt(e.target.value)}
        />

        {mode === "standard" && (
          <>
            <label>
              Категорія:
              <select
                className="create-article-select"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              >
                <option value="sport">Спорт</option>
                <option value="fashion">Мода</option>
                <option value="News">Новини</option>
              </select>
            </label>

            <label className="create-article-checkbox">
              <input
                type="checkbox"
                checked={isPremium}
                onChange={(e) => setIsPremium(e.target.checked)}
              />
              Преміум стаття
            </label>
          </>
        )}

        {mode === "channel" && (
          <label>
            Виберіть канал:
            <select
              className="create-article-select"
              value={selectedChannel}
              onChange={(e) => setSelectedChannel(e.target.value)}
            >
              <option value="">-- Оберіть канал --</option>
              {channels.map((ch) => (
                <option key={ch.id} value={ch.id}>
                  {ch.name}
                </option>
              ))}
            </select>
          </label>
        )}

        {subtype === "standard" && (
          <label>
            Зображення:
            <input
              type="file"
              className="create-article-input"
              onChange={(e) => setImage(e.target.files[0])}
            />
          </label>
        )}

        <button type="submit" className="create-article-button">
          Створити
        </button>

        {message && (
          <p
            className={`create-article-message ${
              message.includes("✅") ? "success" : "error"
            }`}
          >
            {message}
          </p>
        )}
      </form>
    </div>
  );
}
